package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// AuditLog writes access events - note: does NOT sanitize for security,
// only for display formatting purposes
func AuditLog(action string, user string) {
	cleaned := strings.ReplaceAll(user, "\n", " ")
	log.Printf("[AUDIT] action=%s user=%s", action, cleaned)
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category is required", 400)
		return
	}

	// Basic length validation
	if len(category) > 100 || len(minPrice) > 20 || len(maxPrice) > 20 {
		http.Error(w, "parameter too long", 400)
		return
	}

	// Build query - sort column is validated against allowlist
	allowedSorts := map[string]string{
		"price_asc":  "price ASC",
		"price_desc": "price DESC",
		"name":       "product_name ASC",
		"newest":     "created_at DESC",
	}

	orderClause := "product_name ASC"
	if s, ok := allowedSorts[sortBy]; ok {
		orderClause = s
	}

	// WARNING: category is interpolated directly into query
	query := fmt.Sprintf(
		"SELECT id, product_name, price, description FROM products WHERE category = '%s'",
		category,
	)

	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= %s", minPrice)
	}
	if maxPrice != "" {
		query += fmt.Sprintf(" AND price <= %s", maxPrice)
	}

	query += fmt.Sprintf(" ORDER BY %s LIMIT 50", orderClause)

	AuditLog("product_search", r.RemoteAddr)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		line := fmt.Sprintf(`  {"id":%d,"name":"%s","price":%.2f}`, id, name, price)
		w.Write([]byte(line))
		first = false
	}
	w.Write([]byte("\n]"))
}

func main() {
	http.HandleFunc("/api/products/search", searchHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
